 */
plugins {
    java
    id("org.springframework.boot") version "4.1.0"
    id("io.spring.dependency-management") version "1.1.7"
    id("io.freefair.lombok") version "9.5.0"
    jacoco
    id("org.sonarqube") version "7.5.0.8588"
}

sonar {
    properties {
        property("sonar.projectKey", "User57134_hexlet-spring-blog")
        property("sonar.organization", "user57134")
    }
}

group = "io.hexlet"
version = "0.0.1-SNAPSHOT"

repositories {
    mavenCentral()
}

dependencies {
    // Подключаем бд H2
    runtimeOnly("com.h2database:h2")

    // Подключение веб-консоли H2
    implementation("org.springframework.boot:spring-boot-h2console")

    implementation("org.springframework.boot:spring-boot-starter")
    implementation("org.springframework.boot:spring-boot-starter-webmvc")

    // Подключение механизма для валидации:
    // 1) интерфейсы спецификации: jakarta.validation-api;
    // 2) Реализацию (движок): hibernate-validator;
    // 3) Интеграцию со Spring: автоматическую настройку локального валидатора
    //    (LocalValidatorFactoryBean), который связывает движок валидации
    //    со Spring MVC.
    implementation("org.springframework.boot:spring-boot-starter-validation")

    // Поддержка jakarta.persistence.*
    implementation("org.springframework.boot:spring-boot-starter-data-jpa")

    // Добавляет валидацию для сущностей: @NotBlank, @Size, @Valid
    implementation("org.springframework.boot:spring-boot-starter-validation")

    // Подключение библиотеки jackson-databind-nullable: для обертывания полей JsonNullable
    // для разделения случаев при частичном обновлении когда поле отсутствует и
    // когда оно умышленно обнулено
    implementation("org.openapitools:jackson-databind-nullable:0.2.11")

    implementation("org.springframework.boot:spring-boot-devtools")

    // Пакеты с модулями для аутентификации и проверке прав доступа
    implementation("org.springframework.boot:spring-boot-starter-security")
    implementation("org.springframework.boot:spring-boot-starter-oauth2-resource-server")
    testImplementation("org.springframework.security:spring-security-test")

    // Библиотека для генерации случайных данных
    implementation("net.datafaker:datafaker:2.7.0")

    // Библиотека для конвертации в DTO и из DTO
    implementation("org.mapstruct:mapstruct:1.6.3")

    // Процессор аннотаций для MapStruct
    annotationProcessor("org.mapstruct:mapstruct-processor:1.6.3")

    // Процессор аннотаций при тестировании для MapStruct
    testAnnotationProcessor("org.mapstruct:mapstruct-processor:1.6.3")

    // Основной набор для тестирования приложений Spring: JUnit, AssertJ, Mockito, модули работы с JSON
    testImplementation("org.springframework.boot:spring-boot-starter-test")

    // Дает проекту инфраструктуру для тестирования HTTP-эндпоинтов (веб-слоя)
    testImplementation("org.springframework.boot:spring-boot-starter-webmvc-test")

    // Библиоетека для более удобной проверки ответов JSON
    testImplementation("net.javacrumbs.json-unit:json-unit-assertj:6.2.0")

    // Понадобится когда мы начнем работать с аутентификацией
    testImplementation("org.springframework.security:spring-security-test")
}

tasks.withType<Test> {
    // Явное указание - установить профиль 'test' при выполнении тестов
    systemProperty("spring.profiles.active", "test")
    useJUnitPlatform()
    finalizedBy(tasks.jacocoTestReport)
}

tasks.jacocoTestReport {
    dependsOn(tasks.test)
    reports {
        xml.required.set(true)
        html.required.set(true)
    }
}